FROM node:24-alpine

WORKDIR /app/frontend
COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund
COPY . .

EXPOSE 5173
# Refresh the named dependency volume when the mounted lockfile changes.
CMD ["sh", "-c", "npm ci --prefer-offline --no-audit --no-fund && exec npm run dev -- --host 0.0.0.0"]
DATABASE_URL=REDACTED
# PostHog configuration
REDACTED
PUBLIC_POSTHOG_HOST=https://eu.i.posthog.com
import { defineEnvVars } from "@sveltejs/kit/env";

export const variables = defineEnvVars({
  PUBLIC_APP_VERSION: {
    public: true,
    static: true,
    schema: (value) => value || "development",
  },
  PUBLIC_POSTHOG_PROJECT_TOKEN: {
    public: true,
    schema: (value) => value,
  },
  PUBLIC_POSTHOG_HOST: {
    public: true,
    schema: (value) => value,
  },
});
import { dev } from "$app/env";
import {
  PUBLIC_POSTHOG_HOST,
  PUBLIC_POSTHOG_PROJECT_TOKEN,
} from "$app/env/public";
import type { HandleClientError } from "@sveltejs/kit/hooks";
import posthog from "posthog-js";

export function init() {
  const projectToken = REDACTED;
  const host = PUBLIC_POSTHOG_HOST;

  if (!projectToken) {
    if (dev) {
      throw new Error(
        "PUBLIC_POSTHOG_PROJECT_TOKEN variable required by PostHog is missing or un-configured, this causes events to be silently missed. This error stops appearing once PUBLIC_POSTHOG_PROJECT_TOKEN is configured",
      );
    }
    return;
  }

  if (!host) {
    if (dev) {
      throw new Error(
        "PUBLIC_POSTHOG_HOST variable required by PostHog is missing or un-configured, this causes events to be silently missed. This error stops appearing once PUBLIC_POSTHOG_HOST is configured",
      );
    }
    return;
  }

  posthog.init(projectToken, {
    api_host: host,
    logs: {
      serviceName: "exposed-frontend",
      environment: dev ? "development" : "production",
    },
    capture_exceptions: {
      capture_unhandled_errors: true,
      capture_unhandled_rejections: true,
      capture_console_errors: false,
    },
  });
}

export const handleError: HandleClientError = ({ error }) => {
  if (PUBLIC_POSTHOG_PROJECT_TOKEN && PUBLIC_POSTHOG_HOST) {
    posthog.captureException(error);
  }
};
